"""Input checks shared by generated tool wrappers (generated by TerraKernel)."""

from __future__ import annotations

from typing import Any

import numpy as np
import pandas as pd


class ToolInputError(ValueError):
    """Raised when inputs violate the documented preconditions of a tool."""


def as_array(name: str, value: Any, allow_nan: bool = False) -> np.ndarray:
    if isinstance(value, pd.DataFrame):
        raise ToolInputError(f"{name}: expected a Series or array, got a DataFrame")
    arr = np.asarray(value.to_numpy() if isinstance(value, pd.Series) else value, dtype=float)
    if arr.ndim != 1:
        raise ToolInputError(f"{name}: expected a one-dimensional series")
    if arr.size == 0:
        raise ToolInputError(f"{name}: empty input")
    if not allow_nan and np.isnan(arr).any():
        raise ToolInputError(
            f"{name}: contains {int(np.isnan(arr).sum())} missing value(s); select a common valid sample first "
            "(research_tools.common_valid_sample) instead of filling them"
        )
    return arr


def aligned_arrays(**inputs: Any) -> dict[str, np.ndarray]:
    """Convert several series to arrays, requiring equal length and identical indexes for Series."""
    series = {k: v for k, v in inputs.items() if isinstance(v, pd.Series)}
    if len(series) > 1:
        first_key, first = next(iter(series.items()))
        for k, s in series.items():
            if not s.index.equals(first.index):
                raise ToolInputError(f"{k} and {first_key} are not aligned on the same timestamps; "
                                     "use research_tools.common_valid_sample first")
    arrays = {k: as_array(k, v) for k, v in inputs.items()}
    lengths = {len(a) for a in arrays.values()}
    if len(lengths) > 1:
        raise ToolInputError(f"inputs have different lengths: { {k: len(a) for k, a in arrays.items()} }")
    return arrays


def as_number(name: str, value: Any) -> float:
    try:
        x = float(value)
    except (TypeError, ValueError):
        raise ToolInputError(f"{name}: expected a number, got {value!r}") from None
    if np.isnan(x):
        raise ToolInputError(f"{name}: is NaN")
    return x
